content.content:
plugins {
    id 'java-library'
    id 'net.neoforged.moddev' version '2.0.141'
    id 'idea'
}

tasks.named('wrapper', Wrapper).configure {
    distributionType = Wrapper.DistributionType.BIN
}

version = mod_version
group = mod_group_id

repositories {
    maven {
        url "https://www.cursemaven.com"
        content {
            includeGroup "curse.maven"
        }
    }
}

base {
    archivesName = mod_id
}

java.toolchain.languageVersion = JavaLanguageVersion.of(25)

neoForge {
    version = project.neo_version

    runs {
        client {
            client()
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        server {
            server()
            programArgument '--nogui'
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        gameTestServer {
            type = "gameTestServer"
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        data {
            clientData()
            programArguments.addAll '--mod', project.mod_id, '--all', '--output', file('src/generated/resources/').getAbsolutePath(), '--existing', file('src/main/resources/').getAbsolutePath()
            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
        }

        configureEach {
            systemProperty 'forge.logging.markers', 'REGISTRIES'
            logLevel = org.slf4j.event.Level.DEBUG
        }
    }

    mods {
        "${mod_id}" {
            sourceSet(sourceSets.main)
        }
    }
}

sourceSets.main.resources {
    srcDir 'src/generated/resources'
    exclude '.cache'
}
configurations {
    runtimeClasspath.extendsFrom localRuntime
}

dependencies {
    implementation "curse.maven:agritech-evolved-1287394:9155589"

    testImplementation platform("org.junit:junit-bom:5.13.4")
    testImplementation "org.junit.jupiter:junit-jupiter"
    testRuntimeOnly "org.junit.platform:junit-platform-launcher"
}

var generateModMetadata = tasks.register("generateModMetadata", ProcessResources) {
    var replaceProperties = [
            minecraft_version      : minecraft_version,
            minecraft_version_range: minecraft_version_range,
            neo_version            : neo_version,
            loader_version_range   : loader_version_range,
            mod_id                 : mod_id,
            mod_name               : mod_name,
            mod_license            : mod_license,
            mod_version            : mod_version,
    ]
    inputs.properties replaceProperties
    expand replaceProperties
    from "src/main/templates"
    into "build/generated/sources/modMetadata"
}
sourceSets.main.resources.srcDir generateModMetadata
neoForge.ideSyncTask generateModMetadata

tasks.named('test') {
    useJUnitPlatform()
}

tasks.named('jar') {
    from('LICENSE', 'LICENSE-ATE.txt')
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

idea {
    module {
        downloadSources = true
        downloadJavadoc = true
    }
}
org.gradle.jvmargs=-Xmx1G
org.gradle.daemon=true
org.gradle.parallel=true
org.gradle.caching=true
org.gradle.configuration-cache=true

minecraft_version=26.1.2
minecraft_version_range=[26.1.2]
neo_version=26.1.2.121
loader_version_range=[1,)

mod_id=modular_planters
mod_name=Modular Planters
mod_license=MIT
mod_version=0.1.0
mod_group_id=io.github.julianperge.modular_planters
modLoader="javafml"
loaderVersion="${loader_version_range}"
license="${mod_license}"

[[mods]]
modId="${mod_id}"
version="${mod_version}"
displayName="${mod_name}"
authors="Julian Perge"
description='''
An Agritech: Evolved addon that builds multiblock planters out of modular blocks.
'''

[[dependencies.${mod_id}]]
    modId="neoforge"
    type="required"
    versionRange="[${neo_version},)"
    ordering="NONE"
    side="BOTH"

[[dependencies.${mod_id}]]
    modId="minecraft"
    type="required"
    versionRange="${minecraft_version_range}"
    ordering="NONE"
    side="BOTH"

[[dependencies.${mod_id}]]
    modId="agritechevolved"
    type="required"
    versionRange="[2.2.0,)"
    ordering="AFTER"
    side="BOTH"
package io.github.julianperge.modular_planters;

import io.github.julianperge.modular_planters.gametest.MPTestRegistration;
import io.github.julianperge.modular_planters.network.MPNetwork;
import io.github.julianperge.modular_planters.registry.MPBlockEntities;
import io.github.julianperge.modular_planters.registry.MPBlocks;
import io.github.julianperge.modular_planters.registry.MPCreativeTab;
import io.github.julianperge.modular_planters.registry.MPDataComponents;
import io.github.julianperge.modular_planters.registry.MPItems;
import io.github.julianperge.modular_planters.registry.MPMenus;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.ModContainer;
import net.neoforged.fml.common.Mod;
import net.neoforged.fml.config.ModConfig;
import net.neoforged.neoforge.gametest.GameTestHooks;

@Mod(ModularPlanters.MOD_ID)
public class ModularPlanters {
    public static final String MOD_ID = "modular_planters";

    public ModularPlanters(IEventBus modEventBus, ModContainer modContainer) {
        MPBlocks.BLOCKS.register(modEventBus);
        MPItems.ITEMS.register(modEventBus);
        MPBlockEntities.TYPES.register(modEventBus);
        MPDataComponents.COMPONENTS.register(modEventBus);
        MPMenus.MENUS.register(modEventBus);
        modEventBus.addListener(MPBlockEntities::registerCapabilities);
        modEventBus.addListener(MPNetwork::register);
        MPCreativeTab.TABS.register(modEventBus);
        modContainer.registerConfig(ModConfig.Type.SERVER, MPConfig.SPEC);
        if (GameTestHooks.isGametestEnabled()) {
            MPTestRegistration.register(modEventBus);
        }
    }
}
package io.github.julianperge.modular_planters.registry;

import io.github.julianperge.modular_planters.ModularPlanters;
import io.github.julianperge.modular_planters.block.CoreBlock;
import io.github.julianperge.modular_planters.block.ExportBlock;
import io.github.julianperge.modular_planters.block.FertilizerBlock;
import io.github.julianperge.modular_planters.block.PartBlock;
import io.github.julianperge.modular_planters.block.PlanterBlock;
import io.github.julianperge.modular_planters.block.PowerBlock;
import io.github.julianperge.modular_planters.logic.PartType;
import net.minecraft.world.level.block.SoundType;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.neoforged.neoforge.registries.DeferredBlock;
import net.neoforged.neoforge.registries.DeferredRegister;

public final class MPBlocks {
    public static final DeferredRegister.Blocks BLOCKS = DeferredRegister.createBlocks(ModularPlanters.MOD_ID);

    public static final DeferredBlock<CoreBlock> CORE =
            BLOCKS.registerBlock("core", CoreBlock::new, MPBlocks::metal);
    public static final DeferredBlock<PartBlock> FRAME =
            BLOCKS.registerBlock("frame", properties -> new PartBlock(properties, PartType.FRAME), MPBlocks::metal);
    public static final DeferredBlock<PowerBlock> POWER =
            BLOCKS.registerBlock("power", PowerBlock::new, MPBlocks::metal);
    public static final DeferredBlock<FertilizerBlock> FERTILIZER =
            BLOCKS.registerBlock("fertilizer", FertilizerBlock::new, MPBlocks::metal);
    public static final DeferredBlock<ExportBlock> EXPORT =
            BLOCKS.registerBlock("export", ExportBlock::new, MPBlocks::metal);
    public static final DeferredBlock<PlanterBlock> PLANTER =
            BLOCKS.registerBlock("planter", PlanterBlock::new, MPBlocks::metal);

    private MPBlocks() {
    }

    private static BlockBehaviour.Properties metal(BlockBehaviour.Properties properties) {
        return properties.strength(3.0f, 6.0f).requiresCorrectToolForDrops().sound(SoundType.METAL);
    }
}
package io.github.julianperge.modular_planters.registry;

import io.github.julianperge.modular_planters.ModularPlanters;
import net.minecraft.world.item.BlockItem;
import net.neoforged.neoforge.registries.DeferredItem;
import net.neoforged.neoforge.registries.DeferredRegister;

public final class MPItems {
    public static final DeferredRegister.Items ITEMS = DeferredRegister.createItems(ModularPlanters.MOD_ID);

    public static final DeferredItem<BlockItem> CORE = ITEMS.registerSimpleBlockItem(MPBlocks.CORE);
    public static final DeferredItem<BlockItem> FRAME = ITEMS.registerSimpleBlockItem(MPBlocks.FRAME);
    public static final DeferredItem<BlockItem> POWER = ITEMS.registerSimpleBlockItem(MPBlocks.POWER);
    public static final DeferredItem<BlockItem> FERTILIZER = ITEMS.registerSimpleBlockItem(MPBlocks.FERTILIZER);
    public static final DeferredItem<BlockItem> EXPORT = ITEMS.registerSimpleBlockItem(MPBlocks.EXPORT);
    public static final DeferredItem<BlockItem> PLANTER = ITEMS.registerSimpleBlockItem(MPBlocks.PLANTER);

    private MPItems() {
    }
}
package io.github.julianperge.modular_planters.registry;

import io.github.julianperge.modular_planters.ModularPlanters;
import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
