package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.transfer.CombinedResourceHandler;
import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public final class OutputSink {
    private final List<ExportBlockEntity> blocks;
    private final @Nullable MeLink me;
    private final Runnable onStale;
    private final ResourceHandler<ItemResource> extractView = new DelegatingResourceHandler<>(
            () -> new CombinedResourceHandler<>(live().stream().map(ExportBlockEntity::externalHandler).toList()));

    public OutputSink(List<ExportBlockEntity> inOrder, @Nullable MeLink me, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.me = me;
        this.onStale = onStale;
    }

    private List<ExportBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    private @Nullable MeLink liveMe() {
        if (me == null) {
            return null;
        }
        if (me.isRemoved()) {
            onStale.run();
            return null;
        }
        return me;
    }

    public boolean hasRoomFor(List<ItemStack> stacks) {
        try (Transaction tx = Transaction.openRoot()) {
            // ME has no transactions, so stacks that share ME room can both pass, and the part ME refuses later goes to the export blocks or is held in the planter block.
            for (ItemStack stack : stacks) {
                if (!insertInto(stack, tx).isEmpty()) {
                    return false;
                }
            }
            return true;
        }
    }

    public ItemStack insert(ItemStack stack) {
        return insertInto(stack, null);
    }

    public ResourceHandler<ItemResource> extractView() {
        return extractView;
    }

    // ME cannot join a transaction, so each slot gives up the items inside one, offers them to ME, takes back whatever ME refused, and only then commits, which keeps items from being copied or lost.
    public void moveExportsInto(MeLink me) {
        if (!me.online()) {
            return;
        }
        for (ExportBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                ItemResource resource = storage.getResource(slot);
                if (resource.isEmpty()) {
                    continue;
                }
                int asked = (int) me.insertItem(resource, storage.getAmountAsInt(slot), true);
                if (asked == 0) {
                    continue;
                }
                try (Transaction tx = Transaction.openRoot()) {
                    int taken = storage.extract(slot, resource, asked, tx);
                    int accepted = (int) me.insertItem(resource, taken, false);
                    storage.insert(slot, resource, taken - accepted, tx);
                    tx.commit();
                }
            }
        }
    }

    public int fillPercent() {
        long stored = 0;
        long capacity = 0;
        for (ExportBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                stored += storage.getAmountAsLong(slot);
                capacity += storage.getCapacityAsLong(slot, storage.getResource(slot));
            }
        }
        return capacity == 0 ? 0 : (int) (stored * 100 / capacity);
    }

    private ItemStack insertInto(ItemStack stack, @Nullable TransactionContext transaction) {
        if (stack.isEmpty()) {
            return ItemStack.EMPTY;
        }
        ItemResource resource = ItemResource.of(stack);
        int remaining = stack.getCount();
        MeLink link = liveMe();
        if (link != null && link.online()) {
            remaining -= (int) link.insertItem(resource, remaining, transaction != null);
        }
        for (ExportBlockEntity block : live()) {
            if (remaining == 0) {
                break;
            }
            remaining -= ResourceHandlerUtil.insertStacking(block.storage(), resource, remaining, transaction);
        }
        return remaining == 0 ? ItemStack.EMPTY : resource.toStack(remaining);
    }
}
package io.github.julianperge.modular_planters.multiblock;

import com.misterd.agritechevolved.datamap.FertilizerData;
import io.github.julianperge.modular_planters.ate.AteBridge;
import io.github.julianperge.modular_planters.blockentity.FertilizerBlockEntity;
import net.neoforged.neoforge.transfer.CombinedResourceHandler;
import net.neoforged.neoforge.transfer.DelegatingResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public final class FertilizerPool {
    private final List<FertilizerBlockEntity> blocks;
    private final Runnable onStale;
    private final ResourceHandler<ItemResource> insertView = new DelegatingResourceHandler<>(
            () -> new CombinedResourceHandler<>(live().stream().map(FertilizerBlockEntity::externalHandler).toList()));

    public FertilizerPool(List<FertilizerBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<FertilizerBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public ItemResource selected() {
        for (FertilizerBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                ItemResource resource = storage.getResource(slot);
                if (!resource.isEmpty()) {
                    return resource;
                }
            }
        }
        return ItemResource.EMPTY;
    }

    public int available() {
        ItemResource selected = selected();
        if (selected.isEmpty()) {
            return 0;
        }
        long total = 0;
        for (FertilizerBlockEntity block : live()) {
            ItemStacksResourceHandler storage = block.storage();
            for (int slot = 0; slot < storage.size(); slot++) {
                if (storage.getResource(slot).equals(selected)) {
                    total += storage.getAmountAsLong(slot);
                }
            }
        }
        return (int) Math.min(total, Integer.MAX_VALUE);
    }

    public @Nullable FertilizerData data() {
        ItemResource selected = selected();
        return selected.isEmpty() ? null : AteBridge.fertilizer(selected);
    }

    public boolean consume(int count) {
        ItemResource selected = selected();
        if (selected.isEmpty() || count < 0) {
            return false;
        }
        try (Transaction tx = Transaction.openRoot()) {
            int remaining = count;
            for (FertilizerBlockEntity block : live()) {
                if (remaining == 0) {
                    break;
                }
                remaining -= block.storage().extract(selected, remaining, tx);
            }
            if (remaining > 0) {
                return false;
            }
            tx.commit();
            return true;
        }
    }

    public ResourceHandler<ItemResource> insertView() {
        return insertView;
    }

    public void topUpFrom(MeLink me) {
        if (!me.online()) {
            return;
        }
        ItemResource filter = me.fertilizerFilter();
        if (AteBridge.fertilizer(filter) == null) {
            return;
        }
        List<FertilizerBlockEntity> live = live();
        int room;
        // The transaction is never committed, so measuring the room leaves the storage as it was.
        try (Transaction tx = Transaction.openRoot()) {
            room = insertInto(live, filter, Integer.MAX_VALUE, tx);
        }
        if (room == 0) {
            return;
        }
        int taken = (int) me.extractItem(filter, room, false);
        if (taken == 0) {
            return;
        }
        int inserted;
        try (Transaction tx = Transaction.openRoot()) {
            inserted = insertInto(live, filter, taken, tx);
            tx.commit();
        }
        if (inserted < taken) {
            me.insertItem(filter, taken - inserted, false);
        }
    }

    private static int insertInto(List<FertilizerBlockEntity> blocks, ItemResource resource, int amount,
                                  TransactionContext transaction) {
        int inserted = 0;
        for (FertilizerBlockEntity block : blocks) {
            if (inserted == amount) {
                break;
            }
            inserted += ResourceHandlerUtil.insertStacking(block.storage(), resource, amount - inserted, transaction);
        }
        return inserted;
    }

    public Budget budget() {
        FertilizerData data = data();
        return new Budget(this, data, data == null ? 0 : available());
    }

    // Every planter block of a core claims from one budget per tick, in the position order the core ticks them, so claims never add up to more than the pool held when the tick started, and a claim takes items only when its group harvests, one per seed.
    public static final class Budget {
        private final FertilizerPool pool;
        private final @Nullable FertilizerData data;
        private int unclaimed;

        private Budget(FertilizerPool pool, @Nullable FertilizerData data, int unclaimed) {
            this.pool = pool;
            this.data = data;
            this.unclaimed = unclaimed;
        }

        public @Nullable FertilizerData claim(int seeds) {
            if (data == null || seeds > unclaimed) {
                return null;
            }
            unclaimed -= seeds;
            return data;
        }

        public void consume(int count) {
            pool.consume(count);
        }
    }
}
package io.github.julianperge.modular_planters.gametest;

import io.github.julianperge.modular_planters.multiblock.MeLink;
import io.github.julianperge.modular_planters.multiblock.MeStatus;
import java.util.HashMap;
import java.util.Map;
import net.neoforged.neoforge.transfer.item.ItemResource;

public final class FakeMeLink implements MeLink {
    public MeStatus status;
    public boolean removed;
    public ItemResource filter = ItemResource.EMPTY;
    public long energy;
    public long modulateShortfall;

    private final long capacity;
    private final Map<ItemResource, Long> items = new HashMap<>();

    public FakeMeLink(MeStatus status, long capacity) {
        this.status = status;
        this.capacity = capacity;
    }

    public long stored(ItemResource resource) {
        return items.getOrDefault(resource, 0L);
    }

    public void put(ItemResource resource, long amount) {
        items.merge(resource, amount, Long::sum);
    }

    @Override
    public MeStatus status() {
        return status;
    }

    @Override
    public long insertItem(ItemResource resource, long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long total = items.values().stream().mapToLong(Long::longValue).sum();
        long accepted = Math.min(amount, Math.max(0, capacity - total));
        if (simulate) {
            return accepted;
        }
        long inserted = Math.max(0, accepted - modulateShortfall);
        put(resource, inserted);
        return inserted;
    }

    @Override
    public long extractItem(ItemResource resource, long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long extracted = Math.min(amount, stored(resource));
        if (!simulate) {
            items.merge(resource, -extracted, Long::sum);
        }
        return extracted;
    }

    @Override
    public long extractEnergy(long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long extracted = Math.min(amount, energy);
        if (!simulate) {
            energy -= extracted;
        }
        return extracted;
    }

    @Override
    public ItemResource fertilizerFilter() {
        return filter;
    }

    @Override
    public boolean isRemoved() {
        return removed;
    }
}
